cd /work; sqlite3 -header /data/current.db "
-- completeness checks
select 'ops_no_attempts', count(*) from logical_operations o where not exists(select 1 from attempt_events a where a.operation_id=o.operation_id);
select 'gaps', count(*) from (select operation_id, max(attempt_no) mx, count(*) c from attempt_events group by operation_id having mx<>c);
select 'ops_no_assignment', count(*) from logical_operations o where not exists (select 1 from route_assignments r where r.route_id=o.route_id and o.opened_at_ms>=r.effective_from_ms and o.opened_at_ms<r.effective_to_ms);
select 'multi_assignment', count(*) from logical_operations o join route_assignments r on r.route_id=o.route_id and o.opened_at_ms>=r.effective_from_ms and o.opened_at_ms<r.effective_to_ms group by o.operation_id having count(*)>1;
select 'attempt_after_completion', count(*) from attempt_events where completed_at_ms<started_at_ms;
select 'ops_by_route', route_id, count(*) from logical_operations group by route_id;
select 'ops_pq', min(opened_at_ms), max(opened_at_ms) from logical_operations where opened_at_ms>=1777719600000-3600000 and opened_at_ms<1777730400000;
"

